import jax.numpy as jnp
import flax.linen as nn
from jax import random
from typing import Dict, Any, Sequence

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'dropout_rate': 0.1,
        'cnn_features': 32,  # Features per kernel, 32*4=128 total
        'kernel_sizes': [3, 5, 8, 12]
    }

class MultiScaleCNN(nn.Module):
    """A CNN with parallel convolutions of different kernel sizes."""
    d_output: int
    task_type: str
    cnn_features: int
    dropout_rate: float
    kernel_sizes: Sequence[int]

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Create a list of feature maps from parallel convolutions
        feature_maps = []
        for kernel_size in self.kernel_sizes:
            conv_output = nn.Conv(
                features=self.cnn_features,
                kernel_size=(kernel_size,)
            )(x)
            pooled_output = jnp.max(nn.relu(conv_output), axis=1)
            feature_maps.append(pooled_output)

        # Concatenate the feature maps from all scales
        combined_features = jnp.concatenate(feature_maps, axis=-1)

        # Final dense layers
        dropout_layer = nn.Dropout(rate=self.dropout_rate)
        dense_layer = nn.Dense(self.d_output)

        x = dropout_layer(combined_features, deterministic=deterministic)
        x = dense_layer(x)

        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class NetworkWrapper:
    def __init__(self, **kwargs):
        self.network = MultiScaleCNN(**kwargs)

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False,
                                    rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    return NetworkWrapper(
        d_output=hparams["d_output"],
        task_type=hparams["task_type"],
        cnn_features=hparams["cnn_features"],
        dropout_rate=hparams["dropout_rate"],
        kernel_sizes=hparams["kernel_sizes"]
    )
